using System;
using System.Collections.Generic;
using LittleLeo;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.Localization.SmartFormat;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "GrimExchangeRunModifier", menuName = "Data/RunModifiers/GrimExchangeRunModifier", order = 0)]
public class GrimExchangeRunModifier : StartOfBattleRunModifier
{
	public class ReinforcedAmount
	{
		public GameObject Enemy;

		public int Amount;

		public ReinforcedAmount(GameObject Enemy, int Amount)
		{
			this.Enemy = Enemy;
			this.Amount = Amount;
		}
	}

	[SerializeField]
	private int loseCorruptionPercentage;

	[SerializeField]
	private int applyReinforcedPercentage;

	[SerializeField]
	private int voidsmithReinforcedAmount;

	public List<ReinforcedAmount> ReinforcedAmounts = new List<ReinforcedAmount>();

	private Action VoidsmithBattleStartOfTurnAction;

	public float LoseCorruptionPercentage => (0f - (float)loseCorruptionPercentage) / 100f;

	public float ApplyReinforcedPercentage => (float)applyReinforcedPercentage / 100f;

	public override void Initialize()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.GrimExchangeRunModifier = this;
		ReinforcedAmounts.Clear();
		base.Initialize();
	}

	public override UnityAction GetStartOfBattleRunModifierAction()
	{
		return delegate
		{
			OmenLogicActionFace omenLogicActionFace = omenLogicActionFaces.First();
			ReinforcedAmounts.InteractThroughItems(delegate(ReinforcedAmount item)
			{
				omenLogicActionFace.OmenLogic.ActivateOmen(omenLogicActionFace.ActionFace.BattleAction, item.Amount, item.Enemy, null);
			});
		};
	}

	public void VoidsmithBattle(GameObject voidsmithGameObject)
	{
		VoidsmithBattleStartOfTurnAction = delegate
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
			{
				OmenLogicActionFace omenLogicActionFace = omenLogicActionFaces.First();
				omenLogicActionFace.OmenLogic.ActivateOmen(omenLogicActionFace.ActionFace.BattleAction, voidsmithReinforcedAmount, voidsmithGameObject, null);
			});
		};
		ReferenceSingleton<RunModifiersManager>.Instance.StartOfTurnRunModifierActions.Add(VoidsmithBattleStartOfTurnAction);
	}

	public override void EndOfBattleInitialize()
	{
		ReinforcedAmounts.Clear();
		ReferenceSingleton<RunModifiersManager>.Instance.StartOfTurnRunModifierActions.Remove(VoidsmithBattleStartOfTurnAction);
	}

	public override string GetLocalizedDescription()
	{
		return base.localizationManager.GetLocalizedStartOfBattle() + base.localizationManager.GetLocalizedSpace() + Smart.Format(base.localizedDescription, applyReinforcedPercentage, loseCorruptionPercentage);
	}
}
